INSERT INTO "item" ("id","remote_id","source","list_type","title","description","url","mini_program_id","placeholder","icon_path","icon_name","recommend","vip_level","is_highlighted","is_online","is_ai","created_at","updated_at","published_at","document_id","comment_count") VALUES (85,1908,0,6,'祝福メッセージ生成器','すべての祝福を唯一無二のものに。この速いペースの世界で、私たちはあなたが気持ちを伝えたいけれど時間がないことを理解しています。私たちのソフトウェアは、スマートアルゴリズムを通じて、あなたのニーズと感情の色合いに基づき、個性的な祝福の言葉をカスタマイズします。','','','','','',0,0,0,0,0,1786086314671,1786086314671,NULL,'hgzmhbzpk3dc48hz2q5xnse6',NULL);
